import AppKit

/// Help > Keyboard Shortcuts. The menu-bar part is generated by walking the
/// live main menu, so it cannot drift from what the app actually binds; only
/// keys handled outside the menu are listed by hand in `extras`.
final class ShortcutsWindowController: NSWindowController {
    /// Bindings that are not menu items (key monitor, find bar, search panel).
    private static let extras: [(section: String, rows: [(String, String)])] = [
        ("Tabs", [("Next Tab", "⌃⇥"), ("Previous Tab", "⌃⇧⇥")]),
        ("In the All Tabs Switcher", [
            ("Filter", "Type"), ("Move Between Tabs", "↑ ↓  ⌃⇥"), ("Switch to Tab", "↩"), ("Close", "⎋"),
        ]),
        ("In the Find Bar", [
            ("Next Match", "↩"), ("Previous Match", "⇧↩"), ("Close Find Bar", "⎋"),
        ]),
        ("In Search All Tabs", [
            ("Open Selected Result", "↩"), ("Move Between Results", "↑ ↓"), ("Close", "⎋"),
        ]),
        ("Links and Files", [
            ("Open Link to Another Document in a New Tab", "Click"),
            ("Open a Markdown File", "Drop on window or Dock icon"),
        ]),
    ]

    /// Items AppKit injects into the Edit menu itself; not Xem's commands.
    private static let systemTitles: Set<String> = [
        "Writing Tools", "AutoFill", "Start Dictation…", "Emoji & Symbols",
    ]

    private let textView = NSTextView()

    init() {
        let window = PopupWindow(
            contentRect: NSRect(x: 0, y: 0, width: 480, height: 560),
            styleMask: [.titled, .closable, .resizable],
            backing: .buffered,
            defer: false
        )
        window.title = "Keyboard Shortcuts"
        window.isReleasedWhenClosed = false
        window.tabbingMode = .disallowed
        window.minSize = NSSize(width: 400, height: 300)
        super.init(window: window)

        textView.isEditable = false
        textView.drawsBackground = false
        textView.textContainerInset = NSSize(width: 16, height: 14)
        textView.isHorizontallyResizable = false
        textView.autoresizingMask = [.width]

        let scroll = NSScrollView()
        scroll.documentView = textView
        scroll.hasVerticalScroller = true
        scroll.drawsBackground = false
        window.contentView = scroll
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) { fatalError("not supported") }

    func showAndFocus() {
        // Rebuilt each time: menu titles change ("Show/Hide Outline").
        textView.textStorage?.setAttributedString(buildContent())
        window?.center(over: NSApp.keyWindow)
        showWindow(nil)
        window?.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
    }

    // MARK: Content

    private func buildContent() -> NSAttributedString {
        let width = (window?.contentView?.bounds.width ?? 480) - 40
        let paragraph = NSMutableParagraphStyle()
        paragraph.tabStops = [NSTextTab(textAlignment: .right, location: width)]
        paragraph.paragraphSpacing = 3

        let headerStyle = NSMutableParagraphStyle()
        headerStyle.paragraphSpacingBefore = 14
        headerStyle.paragraphSpacing = 4

        let body: [NSAttributedString.Key: Any] = [
            .font: NSFont.systemFont(ofSize: NSFont.systemFontSize),
            .foregroundColor: NSColor.labelColor,
            .paragraphStyle: paragraph,
        ]
        let key: [NSAttributedString.Key: Any] = [
            .font: NSFont.monospacedSystemFont(ofSize: NSFont.systemFontSize - 1, weight: .regular),
            .foregroundColor: NSColor.secondaryLabelColor,
            .paragraphStyle: paragraph,
        ]
        let header: [NSAttributedString.Key: Any] = [
            .font: NSFont.boldSystemFont(ofSize: NSFont.systemFontSize + 1),
            .foregroundColor: NSColor.labelColor,
            .paragraphStyle: headerStyle,
        ]

        let out = NSMutableAttributedString()
        func section(_ title: String, _ rows: [(String, String)]) {
            guard !rows.isEmpty else { return }
            out.append(NSAttributedString(string: title + "\n", attributes: header))
            for (name, shortcut) in rows {
                out.append(NSAttributedString(string: name, attributes: body))
                out.append(NSAttributedString(string: "\t" + shortcut + "\n", attributes: key))
            }
        }

        for (title, rows) in Self.menuSections() { section(title, rows) }
        for extra in Self.extras { section(extra.section, extra.rows) }
        return out
    }

    /// Every titled item in the main menu, grouped by top-level menu.
    private static func menuSections() -> [(String, [(String, String)])] {
        guard let main = NSApp.mainMenu else { return [] }
        var sections: [(String, [(String, String)])] = []
        for top in main.items {
            guard let submenu = top.submenu else { continue }
            var rows: [(String, String)] = []
            for item in submenu.items
            where !item.isSeparatorItem && !item.isHidden && !item.isAlternate
                && item.action != nil && !systemTitles.contains(item.title)
            {
                // AppKit appends one private-action item per open window.
                if let action = item.action, NSStringFromSelector(action).hasPrefix("_") { continue }
                rows.append((item.title, shortcut(for: item)))
            }
            let title = submenu.title.isEmpty ? "Xem" : submenu.title
            sections.append((title, rows))
        }
        return sections
    }

    private static func shortcut(for item: NSMenuItem) -> String {
        // AppKit replaces this item with its own, whose key equivalent carries
        // no modifiers (the system draws Ctrl-Cmd-F itself).
        if item.action == #selector(NSWindow.toggleFullScreen(_:)) { return "⌃⌘F" }
        guard let first = item.keyEquivalent.unicodeScalars.first else { return "" }
        var mods = item.keyEquivalentModifierMask
        let key: String
        switch Int(first.value) {
        case NSLeftArrowFunctionKey: key = "←"
        case NSRightArrowFunctionKey: key = "→"
        case NSUpArrowFunctionKey: key = "↑"
        case NSDownArrowFunctionKey: key = "↓"
        case 9: key = "⇥"
        case 13, 3: key = "↩"
        case 27: key = "⎋"
        case 32: key = "Space"
        case 8, 0x7F: key = "⌫"
        default:
            let text = item.keyEquivalent
            // An uppercase key equivalent means Shift is held.
            if text != text.lowercased() { mods.insert(.shift) }
            key = text.uppercased()
        }
        var symbols = ""
        if mods.contains(.control) { symbols += "⌃" }
        if mods.contains(.option) { symbols += "⌥" }
        if mods.contains(.shift) { symbols += "⇧" }
        if mods.contains(.command) { symbols += "⌘" }
        return symbols + key
    }
}
